<?php
declare(strict_types=1);
namespace Admin\Controllers;
use Core\Http\Request;use Core\Http\Response;use Core\I18n\ContentTranslations;
final class TranslationsController extends Controller{
 public function index(Request $r):Response{$u=$this->user();if(!$u||!$this->auth()->has($u,'content.manage'))return$this->forbidden();$svc=new ContentTranslations($this->db());if($r->isPost()){$action=$r->string('action');if($action==='language')$error=$svc->addLanguage($r->string('locale'),$r->string('name'));else $error=$svc->save((int)$r->string('page_id'),$r->string('locale'),$r->post);if(!$error)$this->audit($action==='language'?'translations.language_added':'translations.page_saved',['locale'=>$r->string('locale'),'page_id'=>(int)$r->string('page_id')]);$this->flash($error?'error':'ok',$error??($action==='language'?'Language added.':'Translation saved.'));return$this->redirect($r,'/admin/translations?page_id='.(int)$r->string('page_id').'&locale='.rawurlencode($r->string('locale')));} $pageId=(int)$r->string('page_id');$locale=$r->string('locale');return$this->page($r,'translations/index',['languages'=>$svc->languages(),'pages'=>$this->db()->fetchAll('SELECT id,title,slug,body,blocks_json,meta_title,meta_description,schema_json FROM `'.$this->db()->table('pages').'` WHERE deleted_at IS NULL ORDER BY title'),'selectedPage'=>$pageId,'selectedLocale'=>$locale,'translation'=>$pageId&&$locale?$svc->forPage($pageId,$locale):null],'Translations');}
}
